@keyframes dotpulse {
  0% {
    transform: scale(0.7);
  }
  50% {
    transform: scale(1.2);
  }
  100% {
    transform: scale(0.7);
  }
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes arrow-slide-right {
  0% {
    transform: translateX(0);
  }
  49.9% {
    transform: translateX(120%);
    opacity: 0;
  }
  50% {
    transform: translateX(-120%);
    opacity: 0;
  }
  100% {
    transform: translateX(0);
    opacity: 1;
  }
}
@keyframes arrow-slide-left {
  0% {
    transform: rotate(180deg) translateX(0);
  }
  49.9% {
    transform: rotate(180deg) translateX(120%);
    opacity: 0;
  }
  50% {
    transform: rotate(180deg) translateX(-120%);
    opacity: 0;
  }
  100% {
    transform: rotate(180deg) translateX(0);
    opacity: 1;
  }
}
